Serie *retorna_preenchido(int *i, Serie **serie)
{
    // Abre o arquivo.
    FILE *arquivo = fopen("streaming_db.csv", "r");
    if (arquivo == NULL)
    {
        perror("\nErro ao abrir o arquivo!\n");
        exit(1);
    }

    // Declarando as variaveis.
    char *pt;
    char vetor_guarda_linha[150];

    // Pula o cabeçalho do CSV
    if (fgets(vetor_guarda_linha, 150, arquivo) == NULL) {
        fclose(arquivo);
        return NULL; // Arquivo vazio
    }

    // Inicializa o vetor de séries (pode ser nulo inicialmente)
    *serie = NULL; 

    while (fgets(vetor_guarda_linha, 150, arquivo) != NULL)
    {
        // Redimensiona o vetor para acomodar o próximo item
        // Nota: Realloc exige que o ponteiro seja modificado, por isso o **serie
        *serie = (Serie *)realloc(*serie, (*i + 1) * sizeof(Serie));
        if (*serie == NULL) {
             perror("Erro de realocação de memória");
             exit(1);
        }

        // Pega uma cópia da linha para poder usar strtok, sem modificar o buffer principal do fgets
        char linha_copia[150];
        strcpy(linha_copia, vetor_guarda_linha);

        pt = strtok(linha_copia, ",");
        (*serie)[*i].codigo = atoi(pt);

        pt = strtok(NULL, ",");
        strcpy((*serie)[*i].titulo, pt);

        pt = strtok(NULL, ",");
        strcpy((*serie)[*i].genero, pt);

        pt = strtok(NULL, ",");
        (*serie)[*i].classificacao = atoi(pt);

        pt = strtok(NULL, ",");
        strcpy((*serie)[*i].plataforma, pt);

        pt = strtok(NULL, ",");
        (*serie)[*i].duracao_media = atoi(pt);

        pt = strtok(NULL, ",");
        (*serie)[*i].quantidade_de_temporada = atoi(pt);

        // Alocação da memória para os episódios
        (*serie)[*i].quantidade_de_ep = (int *)malloc((*serie)[*i].quantidade_de_temporada * sizeof(int));
        if ((*serie)[*i].quantidade_de_ep == NULL) {
            perror("Erro na alocação de episódios");
            exit(1);
        }

        // Leitura dos episódios
        for (int j = 0; j < (*serie)[*i].quantidade_de_temporada; j++)
        {
            // Aqui o separador é ", " (vírgula e espaço) conforme seu código original
            pt = strtok(NULL, ", "); 
            (*serie)[*i].quantidade_de_ep[j] = atoi(pt);
        }
        (*i)++;
    }

    fclose(arquivo);
    return *serie;
}

